int sprintf(char*չափ_տվյալ,const char*նիշք_մուտքագրում,...){va_list 첫째값;va_start(첫째값,նիշք_մուտքագրում);int 반환값=vsnprintf(չափ_տվյալ,SIZE_MAX,նիշք_մուտքագրում,첫째값);va_end(첫째값);return 반환값;}
int vfprintf(FILE*հոսք_արժեք,const char*նիշք_մուտքագրում,va_list 첫째값){char 둘째값[2048];int 개수=vsnprintf(둘째값,sizeof(둘째값),նիշք_մուտքագրում,첫째값);if(개수>2047)개수=2047;return fwrite(둘째값,1,개수,հոսք_արժեք)==(size_t)개수?개수:-1;}
int fprintf(FILE*հոսք_արժեք,const char*նիշք_մուտքագրում,...){va_list 첫째값;va_start(첫째값,նիշք_մուտքագրում);int 반환값=vfprintf(հոսք_արժեք,նիշք_մուտքագրում,첫째값);va_end(첫째값);return 반환값;}
int printf(const char*նիշք_մուտքագրում,...){va_list 첫째값;va_start(첫째값,նիշք_մուտքագրում);int 반환값=vfprintf(stdout,նիշք_մուտքագրում,첫째값);va_end(첫째값);return 반환값;}
